#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

#define ITERATIONS 1000000
#define REPEATS 3

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total ); // TAP plan
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmark results.
*
* @param elapsed   elapsed time in seconds
*/
static void print_results( double elapsed ) {
	double rate = (double)ITERATIONS / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", ITERATIONS );
	printf( "  elapsed: %0.9f\n", elapsed );
	printf( "  rate: %0.9f\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Generates a random number on the interval [0,1).
*
* @return random number
*/
static double rand_double( void ) {
	int r = rand();
	return (double)r / ( (double)RAND_MAX + 1.0 );
}

// log(2**127)
static const float MAXLOG = 8.8029691931113054295988e+01f;

static float rational_pq( const float x ) {
	float ax;
	float ix;
	float s1;
	float s2;
	if ( x == 0.0f ) {
		return -0.3333333333333332f;
	}
	if ( x < 0.0f ) {
		ax = -x;
	} else {
		ax = x;
	}
	if ( ax <= 1.0f ) {
		s1 = -1614.6876844170845f + (x * (-99.28772310019185f + (x * (-0.9643991794250523f + (x * 0.0f)))));
		s2 = 4844.063053251255f + (x * (2235.4883906010045f + (x * (112.81167849163293f + (x * 1.0f)))));
	} else {
		ix = 1.0f / x;
		s1 = 0.0f + (ix * (-0.9643991794250523f + (ix * (-99.28772310019185f + (ix * -1614.6876844170845f)))));
		s2 = 1.0f + (ix * (112.81167849163293f + (ix * (2235.4883906010045f + (ix * 4844.063053251255f)))));
	}
	return s1 / s2;
}

static float cephes_tanhf( const float x ) {
	float s;
	float z;
	z = ( x < 0.0f ) ? -x : x;
	if ( z > 0.5f * MAXLOG ) {
		return ( x < 0.0f ) ? -1.0f : 1.0f;
	}
	if ( z >= 0.625f ) {
		s = expf( 2.0f * z );
		z = 1.0f - ( 2.0f / ( s + 1.0f ) );
		if ( x < 0.0f ) {
			z = -z;
		}
	} else {
		if ( x == 0.0f ) {
			return x;
		}
		s = x * x;
		z = x + ( x * s * rational_pq( s ) );
	}
	return z;
}

/**
* Runs a benchmark.
*
* @return elapsed time in seconds
*/
static double benchmark( void ) {
	float x[ 100 ];
	double elapsed;
	float y;
	double t;
	int i;

	for ( i = 0; i < 100; i++ ) {
		x[ i ] = (float)( ( (double)rand() / ( (double)RAND_MAX + 1.0 ) * 10.0 ) - 5.0 );
	}

	t = (double)clock() / CLOCKS_PER_SEC;
	for ( i = 0; i < ITERATIONS; i++ ) {
		y = cephes_tanhf( x[ i%100 ] );
		if ( y != y ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	elapsed = ( (double)clock() / CLOCKS_PER_SEC ) - t;
	if ( y != y ) {
		printf( "should not return NaN\n" );
	}
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int i;

	srand( (unsigned int)time( NULL ) );

	print_version();
	for ( i = 0; i < REPEATS; i++ ) {
		printf( "# c::cephes_tanhf\n" );
		elapsed = benchmark();
		print_results( elapsed );
		printf( "ok %d benchmark finished\n", i+1 );
	}
	print_summary( REPEATS, REPEATS );
}
